#!/usr/bin/env bash
set -u

# Delete the artifacts generated by one installation, so the next run
# counts as a fresh installation. This does NOT touch .env.example,
# resources/configuration.json, source files, or the virtual environment.

cd "$(dirname "$0")/.."

echo
echo "Akupara - Reset Installation"
echo

echo "Deleting per-installation artifacts..."

if [ -f ".env" ]; then
  rm -f ".env"
  echo "  deleted .env"
else
  echo "  .env not found, skipping"
fi

if [ -f "resources/password-pepper" ]; then
  rm -f "resources/password-pepper"
  echo "  deleted resources/password-pepper"
else
  echo "  resources/password-pepper not found, skipping"
fi

if [ -f "resources/installation.json" ]; then
  rm -f "resources/installation.json"
  echo "  deleted resources/installation.json"
else
  echo "  resources/installation.json not found, skipping"
fi

if [ -d "resources/trust" ]; then
  rm -rf "resources/trust"
  echo "  deleted resources/trust/"
else
  echo "  resources/trust not found, skipping"
fi

if [ -d "logs" ]; then
  rm -rf "logs"
  echo "  deleted logs/"
else
  echo "  logs not found, skipping"
fi

echo
echo "==============================================="
echo "  Per-installation artifacts removed"
echo "==============================================="
echo
echo "Next: scripts/setup.sh (creates a new installation)"
